import{_ as s,o as e,c as i,a5 as t}from"./chunks/framework.BYXPg_yw.js";const k=JSON.parse('{"title":"Audio","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"software/audio.md","filePath":"software/audio.md","lastUpdated":1793350928000}'),o={name:"software/audio.md"};function n(h,a,l,p,r,d){return e(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="audio" tabindex="-1">Audio <a class="header-anchor" href="#audio" aria-label="Permalink to &quot;Audio&quot;">​</a></h1><p>The robot records from a microphone and plays sound files through its speaker. Recording and playback are HTTP requests to port <code>8081</code>, and recordings are downloaded from port <code>8080</code>. Both use the robot&#39;s web account (<code>rb</code> / <code>rainbow2026</code>) as HTTP Basic authentication, and the bodies are JSON.</p><h2 id="audio-devices" tabindex="-1">Which microphone and speaker <a class="header-anchor" href="#audio-devices" aria-label="Permalink to &quot;Which microphone and speaker {#audio-devices}&quot;">​</a></h2><p>The robot uses one microphone and one speaker at a time, and picks them itself.</p><table tabindex="0"><thead><tr><th>Robot</th><th>Microphone</th><th>Speaker</th></tr></thead><tbody><tr><td>PTZ payload loaded</td><td>PTZ camera microphone</td><td>PTZ camera speaker</td></tr><tr><td>No PTZ payload</td><td>Microphone plugged into the robot&#39;s audio input</td><td>Robot speaker</td></tr></tbody></table><p>When the PTZ camera comes up or goes away, the robot switches within about 5 seconds. Check which devices are in use before you record or play: <code>input</code> and <code>output</code> read <code>ptz</code>, <code>robot</code> or <code>none</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rb:rainbow2026</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://192.168.0.10:8081/api/audio/status</span></span></code></pre></div><ul><li><strong>Robot microphone</strong> — the robot&#39;s audio input is listed even when nothing is plugged in, so <code>mic_present</code> alone does not tell you a microphone is there. <code>mic_signal</code> does: <code>1</code> when sound comes in, <code>0</code> when it is almost silent and the jack may be empty. It is measured again at most once a minute while you read the status, so plug the microphone in, wait a minute, then check. Plug it in before you start recording — if you pull it out while recording, the rest of the file is silent.</li><li><strong>Robot speaker</strong> — it is silent while the speaker amplifier is off. Turn on <code>Speaker amp (12V)</code> (<code>Speaker amp</code> on CAN-FD robots) under <strong>Maintenance → Power / System</strong> — see <a href="/RBQ/nightly/manual/gui/maintenance.html#power">Maintenance</a>. The PTZ camera speaker has its own amplifier.</li></ul><h2 id="audio-record" tabindex="-1">Record <a class="header-anchor" href="#audio-record" aria-label="Permalink to &quot;Record {#audio-record}&quot;">​</a></h2><ol><li><p>Start recording. The robot records from the moment it answers, so start talking after the reply. The reply carries the file&#39;s path.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rb:rainbow2026</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PUT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://192.168.0.10:8081/api/audio/record</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">     -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;state&quot;:&quot;start&quot;,&quot;source&quot;:&quot;mic&quot;}&#39;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># {&quot;path&quot;:&quot;20261026/mic_20261026_143000.wav&quot;, ...}</span></span></code></pre></div><p>With no microphone the request fails with <code>no microphone</code>.</p></li><li><p>Stop recording. The file is complete only after this — a file still being recorded reads as 0 seconds long.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rb:rainbow2026</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PUT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://192.168.0.10:8081/api/audio/record</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">     -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;state&quot;:&quot;stop&quot;}&#39;</span></span></code></pre></div></li><li><p>Download the file. <code>GET /api/audio/list</code> on the same port lists the recordings.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rb:rainbow2026</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rec.wav</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">     &#39;http://192.168.0.10:8080/api/audio/file?path=20261026/mic_20261026_143000.wav&#39;</span></span></code></pre></div></li></ol><p>A file is closed after 30 minutes. Starting a recording while one is running closes the first file and starts a new one.</p><h2 id="audio-play" tabindex="-1">Play a sound file <a class="header-anchor" href="#audio-play" aria-label="Permalink to &quot;Play a sound file {#audio-play}&quot;">​</a></h2><ol><li><p>Upload the file as base64 in pieces: send each piece with its byte <code>offset</code> and the file&#39;s <code>total</code> size, up to 50 MB in all. When the last piece arrives the robot converts the file for playback and replies with its path. Anything past 10 minutes is cut off.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rb:rainbow2026</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://192.168.0.10:8081/api/audio/upload</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">     -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">     -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;name&quot;:&quot;alarm&quot;,&quot;offset&quot;:0,&quot;total&quot;:&lt;bytes&gt;,&quot;data&quot;:&quot;&lt;base64&gt;&quot;}&#39;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># last piece: {&quot;path&quot;:&quot;library/alarm.wav&quot;, ...}</span></span></code></pre></div></li><li><p>Play it. With <code>&quot;loop&quot;:true</code> it repeats, for up to 30 minutes.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rb:rainbow2026</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PUT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://192.168.0.10:8081/api/audio/play</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">     -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;path&quot;:&quot;library/alarm.wav&quot;,&quot;loop&quot;:false}&#39;</span></span></code></pre></div></li><li><p>Stop it with <code>{&quot;state&quot;:&quot;stop&quot;}</code> on the same request. Playing another file replaces the one that is playing.</p></li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Playback shares the one speaker with the operator app&#39;s <code>Talk</code>. If the operator app is connected and then disconnects, playback stops with it.</p></div><h2 id="audio-ptz" tabindex="-1">Live audio with the PTZ camera <a class="header-anchor" href="#audio-ptz" aria-label="Permalink to &quot;Live audio with the PTZ camera {#audio-ptz}&quot;">​</a></h2><p>The robot&#39;s own interface records and plays files only. For live audio, use the PTZ camera directly at <code>192.168.0.100</code>:</p><ul><li><strong>Microphone</strong> — the camera&#39;s <code>profile4</code> RTSP stream (<code>rtsp://&lt;user&gt;:&lt;password&gt;@192.168.0.100:554/profile4/media.smp</code>) carries the microphone track. Receive it, or save the stream to record.</li><li><strong>Speaker</strong> — open the camera&#39;s ONVIF audio back-channel: the same <code>profile4</code> with the header <code>Require: www.onvif.org/ver20/backchannel</code>, then SETUP the <code>sendonly</code> track and PLAY. Sound you send after the PLAY reply comes out at once. Send G.711 μ-law (PCMU) at 8 kHz, 160 bytes every 20 ms, and keep sending silent frames while no one talks. Close the session (TEARDOWN) when you are done.</li></ul><p>The camera has a 25 W speaker. For its audio settings, see the SUNAPI reference.</p><p>The robot uses the same back-channel for file playback and the operator app&#39;s <code>Talk</code>, so do not use both at once. The robot closes its back-channel 2 seconds after its sound ends. See <a href="/RBQ/nightly/software/ptz-camera-api.html">PTZ Camera</a> for the camera account and SUNAPI.</p>`,19)])])}const u=s(o,[["render",n]]);export{k as __pageData,u as default};
